"""Incident readiness, response playbooks, tabletop exercises and interview preparation (curated guidance).

Structure follows NIST SP 800-61 Rev. 3, which organises incident response around the NIST CSF 2.0
functions (Govern, Identify, Protect, Detect, Respond, Recover). Nothing here is organisation-specific until
the analyst adds facts; playbooks never invent contacts, architecture or legal obligations; they leave
clearly marked blanks instead.
"""
from __future__ import annotations

# ------------------------------------------------------------------ incident scenarios
SCENARIOS: dict[str, dict] = {
    "account_compromise": {"title": "Employee account compromise", "summary": "An attacker has signed in to one or more user accounts, typically email and SaaS."},
    "bec": {"title": "Business email compromise", "summary": "A mailbox is used, or impersonated, to redirect payments or obtain information."},
    "ransomware": {"title": "Ransomware", "summary": "Systems are encrypted and data may have been stolen for extortion."},
    "data_exfiltration": {"title": "Data theft", "summary": "Sensitive data has been copied out of the organisation."},
    "cloud_compromise": {"title": "Compromised cloud service", "summary": "An attacker has access to cloud accounts, subscriptions or SaaS administration."},
    "supply_chain": {"title": "Supplier or software supply-chain compromise", "summary": "A supplier, MSP or software component used by the organisation is compromised."},
    "server_compromise": {"title": "Critical server or appliance compromise", "summary": "A server or internet-facing appliance has been exploited or accessed."},
    "web_intrusion": {"title": "Web application intrusion", "summary": "A public web application has been exploited."},
    "operations_disruption": {"title": "Manufacturing or operations disruption", "summary": "Production or operational systems are affected, directly or through precautionary shutdown."},
    "insider": {"title": "Insider data theft", "summary": "An employee or contractor has taken data without authorisation."},
    "ddos": {"title": "Denial of service", "summary": "Public services are unavailable because of a traffic flood."},
}

ALL = "all"

# ------------------------------------------------------------------ readiness questions
def _q(area, text, why, scenarios, improve, owner, critical=False, refs=()):
    return {"area": area, "text": text, "why": why, "scenarios": scenarios, "improve": improve, "owner": owner, "critical": critical, "refs": list(refs)}


