def interview_questions(role: str, job_description: str = "") -> list[str]:
    level = role_level(role)
    return [k for k, q in INTERVIEW.items() if level in q["roles"]]


def role_level(role: str) -> str:
    r = role.lower()
    return "lead" if any(w in r for w in ("lead", "manager", "head", "principal")) else "senior" if "senior" in r else \
        "engineer" if any(w in r for w in ("engineer", "detection")) else "analyst"
